//! 🧪️ The actual child VCS unit crosses capture, result and acknowledgement only under its initiating caller.
use super::*;
use semio_framework_plugin_job::reserved_jobs::child_vcs::ChildVcsCommandUnit as Unit;
#[test]fn original_child_vcs_unit_drives_real_checkpoint_and_closes_every_cancelled_prefix(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for cut in law["cuts"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([None]){
 let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};let result=crate::original_replay_publication::prepare_report(&mut store,&mut caller,&mut decoder);crate::original_stream_abort::close_report_fixture(result,&mut caller,&mut decoder);let message=law["message"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize);let pointer=message.as_ptr();let mut request=Some(store::ArtifactNativeVcsRequest::CommitCheckpoint{message:Some(message),authors:Vec::new()});let mut source=None;let d=Unit::capture_demands();for axis in [0,1,2,4]{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,2=>denied.maximum_capacity_bytes=d.capacity_bytes-1,_=>denied.maximum_depth=0};turn(&mut caller,&mut decoder,denied,|cx|{assert!(!Unit::admit(&mut request,cx,&mut source)?);Ok(())});assert!(request.is_some()&&source.is_none());}turn(&mut caller,&mut decoder,g,|cx|{assert!(Unit::admit(&mut request,cx,&mut source)?);Ok(())});assert!(request.is_none());for index in 0..262144{if cut==Some(index)||source.as_ref().unwrap().ready(){break}turn(&mut caller,&mut decoder,g,|cx|source.as_mut().unwrap().advance(&mut *store,cx));assert!(index<262143);}if cut.is_none(){let mut result=None;turn(&mut caller,&mut decoder,g,|cx|{assert!(source.as_mut().unwrap().take_result(cx,&mut result)?);Ok(())});assert_eq!(result.unwrap().kind,store::ArtifactNativeVcsKind::CommitCheckpoint);assert_eq!(store.parts_ref().log.envelope.vcs.checkpoints.get(0).unwrap().message.as_ref().unwrap().as_ptr(),pointer);}else{caller.cancel().cancel_now();}
 for index in 0..262144{if source.as_ref().unwrap().terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|source.as_mut().unwrap().close_step(&mut *store,cx)));assert!(index<262143);}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=Unit::release_demands();close_original_retained_step(cx,d,|_|{source.take();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 }
}
